1: % Analytic illustration, not experimental data. Source: transport_theory.tex,
2: % rem:naive-width-band-counterexample and prop:reference-width-floor.
3: % Chosen slice D=log(4), beta=1, m=b=0. The metric unit balls use equal axes:
4: % E(Vbar) has radii (1,1); E(V) has radii (1/2,2). The plotted score bands are
5: % reference [-1,1], uncertified naive [-1/2,1/2], transported [-1,1].
6: % Native body-size TikZ; no external data, rescaling, or extra TikZ libraries.
7: \begin{tikzpicture}[x=1cm,y=1cm,
8:   every node/.style={font=\normalsize,inner sep=0pt},
9:   reference/.style={blue!65!black,line width=1pt},
10:   current/.style={orange!80!black,line width=1pt,dashed},
11:   transported/.style={teal!70!black,line width=1pt}]
12:   \path[use as bounding box] (0,-8.35) rectangle (16.2,.25);
13:   \node[anchor=west] at (0,0)
14:     {\textbf{Abstract illustration}\quad
15:      $\bVbar=\bI_2$, $\bV=\operatorname{diag}(e^D,e^{-D})$,
16:      $\bq=(1,0)^\top$, $m=b=0$.};
17:   \node[anchor=west] at (0,-.55)
18:     {Illustrative slice: $D=\log 4$, $\beta=1$; choose the allowed mean $\mu^*=\beta=1$.};
19: 
20:   \node[anchor=west] at (0,-1.25) {\textbf{Metric unit balls}};
21:   \node[anchor=west] at (0,-1.8) {$E(M)=\{z:z^\top Mz\le1\}$};
22:   \node[anchor=west] at (7,-1.25) {\textbf{Bands along the query direction}};
23: 
24:   % Equal coordinate scales: 1.05 cm per unit in both directions.
25:   \draw[black!40,->,line width=.45pt] (1.05,-4.35) -- (5.2,-4.35)
26:     node[right=3pt] {$z_1$};
27:   \draw[black!40,->,line width=.45pt] (3,-6.7) -- (3,-2);
28:   \node[anchor=west] at (3.6,-2.35) {$z_2$};
29:   \draw[reference,fill=blue!4] (3,-4.35) circle[radius=1.05cm];
30:   \draw[current,fill=orange!6,fill opacity=.55]
31:     (3,-4.35) ellipse[x radius=.525cm,y radius=2.1cm];
32:   \draw[black,->,line width=.7pt] (3,-4.35) -- (4.6,-4.35);
33:   \node[anchor=north] at (4.6,-4.53) {$\bq=\mathbf e_1$};
34:   \fill[orange!80!black] (3.525,-4.35) circle[radius=2pt];
35:   \fill[blue!65!black] (4.05,-4.35) circle[radius=2pt];
36:   \draw[orange!80!black,line width=.45pt]
37:     (3.525,-4.32) -- (3.525,-3.6) -- (4.4,-3.6);
38:   \node[anchor=west] at (4.47,-3.6) {$s=\tfrac12$};
39:   \draw[blue!65!black,line width=.45pt]
40:     (4.05,-4.32) -- (4.05,-3.02) -- (4.4,-3.02);
41:   \node[anchor=west] at (4.47,-3.02) {$\bar s=1$};
42:   \draw[reference] (0,-7.15) -- (.65,-7.15);
43:   \node[anchor=west] at (.82,-7.15) {Reference $E(\bVbar)$};
44:   \draw[current] (3.55,-7.15) -- (4.2,-7.15);
45:   \node[anchor=west] at (4.37,-7.15) {Current $E(\bV)$};
46: 
47:   % One common horizontal value scale: value v is placed at x=11.5+3v.
48:   \draw[black!30,line width=.45pt] (11.5,-2.1) -- (11.5,-6.35);
49:   \draw[black!55,densely dotted,line width=.55pt]
50:     (14.5,-1.95) -- (14.5,-6.35);
51:   \node[anchor=south] at (14.5,-1.8) {$\mu^*=1$};
52: 
53:   \node[anchor=west] at (7,-2.25) {Reference: $m\pm\beta\bar s$};
54:   \draw[reference] (8.5,-2.85) -- (14.5,-2.85);
55:   \draw[reference] (8.5,-2.73) -- (8.5,-2.97);
56:   \draw[reference] (14.5,-2.73) -- (14.5,-2.97);
57:   \fill[black] (14.5,-2.85) circle[radius=2.2pt];
58: 
59:   \node[anchor=west] at (7,-3.75)
60:     {Naive: $m\pm\beta s$\quad (uncertified)};
61:   \draw[current] (10,-4.35) -- (13,-4.35);
62:   \draw[current] (10,-4.23) -- (10,-4.47);
63:   \draw[current] (13,-4.23) -- (13,-4.47);
64:   \fill[black] (14.5,-4.35) circle[radius=2.2pt];
65:   \node[anchor=west] at (14.72,-4.35) {misses $\mu^*$};
66: 
67:   \node[anchor=west] at (7,-5.25)
68:     {Transported: $m\pm\beta e^{D/2}s$};
69:   \draw[transported] (8.5,-5.85) -- (14.5,-5.85);
70:   \draw[transported] (8.5,-5.73) -- (8.5,-5.97);
71:   \draw[transported] (14.5,-5.73) -- (14.5,-5.97);
72:   \fill[black] (14.5,-5.85) circle[radius=2.2pt];
73: 
74:   \draw[black!50,line width=.45pt] (8.15,-6.7) -- (14.85,-6.7);
75:   \foreach \x/\lab in {8.5/-1,10/-\frac12,11.5/0,13/\frac12,14.5/1}{
76:     \draw[black!50,line width=.45pt] (\x,-6.64) -- (\x,-6.76);
77:     \node[anchor=north] at (\x,-6.86) {$\lab$};
78:   }
79:   \node[anchor=north] at (11.5,-7.4) {Mean / score value};
80:   \node[anchor=west] at (0,-7.85)
81:     {$\bar s=1$, $s=e^{-D/2}$; transport restores $e^{D/2}s=\bar s$ in this direction.};
82:   \node[anchor=west] at (0,-8.32)
83:     {This is not a realized learning trajectory or an observed policy failure.};
84: \end{tikzpicture}
